// errUnsupportedProtocol is the error for a call in a protocol the service lacks.
func errUnsupportedProtocol(rc *request.Context) *awserr.Error {
	return &awserr.Error{
		Code:       "InvalidAction",
		Message:    "The sqs service does not accept this protocol.",
		StatusCode: 400,
		Fault:      awserr.FaultSender,
	}
}

// asError turns what a handler returned into the error that goes on the wire.
func asError(err error) *awserr.Error {
	var ae *awserr.Error
	if errors.As(err, &ae) && ae != nil {
		return ae
	}
	return awserr.Internal(err.Error())
}

// writeError writes err in the error form of the caller's protocol.
func writeError(w http.ResponseWriter, rc *request.Context, err *awserr.Error) {
	switch rc.Protocol {
	case protocol.KindJSON:
		opts := awsjson.ErrorOptions{
			QueryCompatible: awsQueryCompatible,
			ContentType:     "application/x-amz-json-" + jsonVersion,
		}
		awsjson.WriteError(w, rc.Request, rc.RequestID, err, opts)
	case protocol.KindQuery:
		env := &query.Envelope{Namespace: queryNamespace, RequestID: rc.RequestID, EscapeQuotes: queryEscapeQuotes}
		query.WriteError(w, env, err)
	default:
		http.Error(w, err.Message, err.StatusCode)
	}
}

func readBody(rc *request.Context) ([]byte, *awserr.Error) {
	body, err := io.ReadAll(protocol.LimitBody(rc.Request.Body))
	if err != nil {
		return nil, &awserr.Error{
			Code:       "SerializationException",
			Message:    "The request body could not be read.",
			StatusCode: 400,
			Fault:      awserr.FaultSender,
		}
	}
	if protocol.OverBody(len(body)) {
		return nil, query.MalformedQueryString()
	}
	if !utf8.Valid(body) {
		return nil, errBodyNotUTF8
	}
	// A handler that refuses a number echoes the text sent, which only the body holds.
	rc.Request.Body = io.NopCloser(bytes.NewReader(body))
	return body, nil
}

// errBodyNotUTF8 is the answer to a json body that is not valid UTF-8: the same as
// broken json and a lone surrogate escape (awsjson.Decode). LocalStack answers 500
// here, which is a crash in its parser and not an answer to copy.
var errBodyNotUTF8 = &awserr.Error{
	Code:       "SerializationException",
	Message:    "Start of structure or map found where not expected.",
	StatusCode: 400,
	Fault:      awserr.FaultSender,
}

// readForm gives the parameters of a query call as LocalStack reads them: the URL's
// before the body's, with no ";" separator and a malformed escape kept as typed.
